if limitInt, e := strconv.Atoi(l); e == nil {
db = db.Limit(limitInt)
}
} else if tpl.Limit > 0 {
db = db.Limit(tpl.Limit)
}

if o := values.Get("offset"); o != "" {
if offsetInt, e := strconv.Atoi(o); e == nil {
