}
}
}

file.SetActiveSheet(sheetIndex)
buffer, err := file.WriteToBuffer()
if err != nil {
return nil, "", err
}
return buffer, tpl.Name, nil
}



func (svc *SysExportTemplateService) ExportTemplate(templateID string) (*bytes.Buffer, string, error) {
