type SysExportTemplateService struct {
}



func (sysExportTemplateService *SysExportTemplateService) CreateSysExportTemplate(sysExportTemplate *system.SysExportTemplate) (err error) {
err = global.GVA_DB.Create(sysExportTemplate).Error
return err
}



func (sysExportTemplateService *SysExportTemplateService) DeleteSysExportTemplate(sysExportTemplate system.SysExportTemplate) (err error) {
err = global.GVA_DB.Delete(&sysExportTemplate).Error
return err
}



func (sysExportTemplateService *SysExportTemplateService) DeleteSysExportTemplateByIds(ids request.IdsReq) (err error) {
err = global.GVA_DB.Delete(&[]system.SysExportTemplate{}, "id in ?", ids.Ids).Error
return err
}



func (sysExportTemplateService *SysExportTemplateService) UpdateSysExportTemplate(sysExportTemplate system.SysExportTemplate) (err error) {
return global.GVA_DB.Transaction(func(tx *gorm.DB) error {
conditions := sysExportTemplate.Conditions
e := tx.Delete(&[]system.Condition{}, "template_id = ?", sysExportTemplate.TemplateID).Error
if e != nil {
return e
}
sysExportTemplate.Conditions = nil

joins := sysExportTemplate.JoinTemplate
e = tx.Delete(&[]system.JoinTemplate{}, "template_id = ?", sysExportTemplate.TemplateID).Error
if e != nil {
return e
}
sysExportTemplate.JoinTemplate = nil

e = tx.Updates(&sysExportTemplate).Error
if e != nil {
return e
}
if len(conditions) > 0 {
for i := range conditions {
conditions[i].ID = 0
}
e = tx.Create(&conditions).Error
}
if len(joins) > 0 {
for i := range joins {
joins[i].ID = 0
}
e = tx.Create(&joins).Error
}
return e
})
}



func (sysExportTemplateService *SysExportTemplateService) GetSysExportTemplate(id uint) (sysExportTemplate system.SysExportTemplate, err error) {
err = global.GVA_DB.Where("id = ?", id).Preload("JoinTemplate").Preload("Conditions").First(&sysExportTemplate).Error
return
}



func (svc *SysExportTemplateService) GetSysExportTemplateInfoList(req systemReq.SysExportTemplateSearch) ([]system.SysExportTemplate, int64, error) {
var (
templates []system.SysExportTemplate
total int64
)

pageSize := req.PageSize
pageOffset := pageSize * (req.Page - 1)

query := global.GVA_DB.Model(&system.SysExportTemplate{})


if req.StartCreatedAt != nil && req.EndCreatedAt != nil {
query = query.Where("created_at BETWEEN ? AND ?", req.StartCreatedAt, req.EndCreatedAt)
}
if req.Name != "" {
query = query.Where("name LIKE ?", "%"+req.Name+"%")
}
if req.TableName != "" {
query = query.Where("table_name = ?", req.TableName)
}
if req.TemplateID != "" {
query = query.Where("template_id = ?", req.TemplateID)
}


if err := query.Count(&total).Error; err != nil {
return nil, 0, err
}


if pageSize > 0 {
query = query.Limit(pageSize).Offset(pageOffset)
}


err := query.Find(&templates).Error
return templates, total, err
}



func (svc *SysExportTemplateService) ExportExcel(templateID string, values url.Values) (*bytes.Buffer, string, error) {
var tpl system.SysExportTemplate
if err := global.GVA_DB.Preload("Conditions").Preload("JoinTemplate").First(&tpl, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

file := excelize.NewFile()
defer func() {
if err := file.Close(); err != nil {
fmt.Println(err)
}
}()

sheetIndex, err := file.NewSheet("Sheet1")
if err != nil {
fmt.Println(err)
return nil, "", err
}

columns, err := utils.GetJSONKeys(tpl.TemplateInfo)
if err != nil {
return nil, "", err
}

var tplMap map[string]string
if err := json.Unmarshal([]byte(tpl.TemplateInfo), &tplMap); err != nil {
return nil, "", err
}

headers := make([]string, len(columns))
for i, key := range columns {
headers[i] = tplMap[key]
}

var dataRows [][]string
dataRows = append(dataRows, headers)

selectExpr := strings.Join(columns, ", ")
db := global.GVA_DB
if tpl.DBName != "" {
db = global.MustGetGlobalDBByDBName(tpl.DBName)
}

if len(tpl.JoinTemplate) > 0 {
for _, join := range tpl.JoinTemplate {
db = db.Joins(join.JOINS + "`" + join.Table + "` ON " + join.ON)
}
}

db = db.Select(selectExpr).Table(tpl.TableName)

for _, cond := range tpl.Conditions {
val := values.Get(cond.From)
if val == "" {
continue
}
if cond.Operator == "LIKE" {
val = "%" + val + "%"
}
db = db.Where(fmt.Sprintf("%s %s ?", cond.Column, cond.Operator), val)
}

if l := values.Get("limit"); l != "" {
if limitInt, e := strconv.Atoi(l); e == nil {
db = db.Limit(limitInt)
}
} else if tpl.Limit > 0 {
db = db.Limit(tpl.Limit)
}

if o := values.Get("offset"); o != "" {
if offsetInt, e := strconv.Atoi(o); e == nil {
db = db.Offset(offsetInt)
}
}


order := values.Get("order")
if order != "" {
db = db.Order(order)
} else if tpl.Order != "" {
db = db.Order(tpl.Order)
}

var resultSet []map[string]interface{}
if err := db.Debug().Find(&resultSet).Error; err != nil {
return nil, "", err
}

for _, rowMap := range resultSet {
row := make([]string, 0, len(columns))
for _, col := range columns {
origCol := col
if len(tpl.JoinTemplate) > 0 {
if parts := strings.Split(origCol, " as "); len(parts) > 1 {
col = strings.TrimSpace(parts[1])
} else if parts := strings.Split(origCol, "."); len(parts) > 1 {
col = parts[1]
}
}
row = append(row, fmt.Sprintf("%v", rowMap[col]))
}
dataRows = append(dataRows, row)
}

for i, row := range dataRows {
for j, cell := range row {
if err := file.SetCellValue("Sheet1", fmt.Sprintf("%s%d", getColumnName(j+1), i+1), cell); err != nil {
return nil, "", err
}
}
}

file.SetActiveSheet(sheetIndex)
buffer, err := file.WriteToBuffer()
if err != nil {
return nil, "", err
}
return buffer, tpl.Name, nil
}



func (svc *SysExportTemplateService) ExportTemplate(templateID string) (*bytes.Buffer, string, error) {
var template system.SysExportTemplate

if err := global.GVA_DB.First(&template, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

f := excelize.NewFile()
defer func() {
if cerr := f.Close(); cerr != nil {
fmt.Println(cerr)
}
}()

sheetName := "Sheet1"
sheetIndex, err := f.NewSheet(sheetName)
if err != nil {
fmt.Println(err)
return nil, "", err
}

columns, err := utils.GetJSONKeys(template.TemplateInfo)
if err != nil {
return nil, "", err
}

var templateInfo map[string]string
if err := json.Unmarshal([]byte(template.TemplateInfo), &templateInfo); err != nil {
return nil, "", err
}

var headers []string
for _, key := range columns {
headers = append(headers, templateInfo[key])
}

for i, header := range headers {
cell := fmt.Sprintf("%s%d", getColumnName(i+1), 1)
if err := f.SetCellValue(sheetName, cell, header); err != nil {
return nil, "", err
}
}

f.SetActiveSheet(sheetIndex)

buffer, err := f.WriteToBuffer()
if err != nil {
return nil, "", err
}

return buffer, template.Name, nil
}



func (sysExportTemplateService *SysExportTemplateService) ImportExcel(templateID string, file *multipart.FileHeader) (err error) {
var template system.SysExportTemplate
err = global.GVA_DB.First(&template, "template_id = ?", templateID).Error
if err != nil {
return err
}

src, err := file.Open()
if err != nil {
return err
}
defer src.Close()

f, err := excelize.OpenReader(src)
if err != nil {
return err
}

rows, err := f.GetRows("Sheet1")
if err != nil {
return err
}

var templateInfoMap = make(map[string]string)
err = json.Unmarshal([]byte(template.TemplateInfo), &templateInfoMap)
if err != nil {
return err
}

var titleKeyMap = make(map[string]string)
for key, title := range templateInfoMap {
titleKeyMap[title] = key
}

db := global.GVA_DB
if template.DBName != "" {
db = global.MustGetGlobalDBByDBName(template.DBName)
}

return db.Transaction(func(tx *gorm.DB) error {
excelTitle := rows[0]
values := rows[1:]
items := make([]map[string]interface{}, 0, len(values))
for _, row := range values {
var item = make(map[string]interface{})
for ii, value := range row {
key := titleKeyMap[excelTitle[ii]]
item[key] = value
}

needCreated := tx.Migrator().HasColumn(template.TableName, "created_at")
needUpdated := tx.Migrator().HasColumn(template.TableName, "updated_at")

if item["created_at"] == nil && needCreated {
item["created_at"] = time.Now()
}
if item["updated_at"] == nil && needUpdated {
item["updated_at"] = time.Now()
}

items = append(items, item)
}
cErr := tx.Table(template.TableName).CreateInBatches(&items, 1000).Error
return cErr
})
}

func getColumnName(n int) string {
columnName := ""
for n > 0 {
n--
columnName = string(rune('A'+n%26)) + columnName
n /= 26
}
return columnName
}

