return nil, err
}


severityStats, err := p.getCountBySeverity(userID, filter.Status)
if err != nil {
return nil, err
}


return &EventsResponse{
Events: result,
PageSize: filter.Limit,
TotalCount: total,
CountBySeverityLevel: severityStats,
}, nil
}

