func (svc *SysExportTemplateService) ImportExcel(templateID string, file *multipart.FileHeader) error {
var tpl system.SysExportTemplate
if err := global.GVA_DB.First(&tpl, "template_id = ?", templateID).Error; err != nil {
return err
}

srcFile, err := file.Open()
if err != nil {
return err
}
defer srcFile.Close()

excelFile, err := excelize.OpenReader(srcFile)
if err != nil {
return err
}

sheetRows, err := excelFile.GetRows("Sheet1")
if err != nil {
return err
}
if len(sheetRows) < 2 {
return errors.New("Excel 数据不足")
}


var fieldMap map[string]string
if err := json.Unmarshal([]byte(tpl.TemplateInfo), &fieldMap); err != nil {
return err
}


titleToKey := make(map[string]string)
for k, v := range fieldMap {
titleToKey[v] = k
}

db := global.GVA_DB
if tpl.DBName != "" {
db = global.MustGetGlobalDBByDBName(tpl.DBName)
}

return db.Transaction(func(tx *gorm.DB) error {
header := sheetRows[0]
dataRows := sheetRows[1:]

records := make([]map[string]interface{}, 0, len(dataRows))
for _, row := range dataRows {
entry := make(map[string]interface{})
for colIdx, val := range row {
if colIdx >= len(header) {
continue
}
if key, ok := titleToKey[header[colIdx]]; ok {
entry[key] = val
}
}


if tx.Migrator().HasColumn(tpl.TableName, "created_at") && entry["created_at"] == nil {
entry["created_at"] = time.Now()
}
if tx.Migrator().HasColumn(tpl.TableName, "updated_at") && entry["updated_at"] == nil {
entry["updated_at"] = time.Now()
}

records = append(records, entry)
}

return tx.Table(tpl.TableName).CreateInBatches(&records, 1000).Error
})
}

func getColumnName(n int) string {
columnName := ""
for n > 0 {
n--
columnName = string(rune('A'+n%26)) + columnName
n /= 26
}
return columnName
}

