func (svc *SysExportTemplateService) ExportExcel(templateID string, values url.Values) (*bytes.Buffer, string, error) {
var template system.SysExportTemplate
if err := global.GVA_DB.Preload("Conditions").Preload("JoinTemplate").First(&template, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

xlsx := excelize.NewFile()
defer func() {
if cerr := xlsx.Close(); cerr != nil {
fmt.Println(cerr)
}
}()

sheetIdx, err := xlsx.NewSheet("Sheet1")
if err != nil {
fmt.Println(err)
return nil, "", err
}

columns, err := utils.GetJSONKeys(template.TemplateInfo)
if err != nil {
return nil, "", err
}

var colMap map[string]string
if err := json.Unmarshal([]byte(template.TemplateInfo), &colMap); err != nil {
return nil, "", err
}

headers := make([]string, len(columns))
for i, key := range columns {
headers[i] = colMap[key]
}

rows := [][]string{headers}


db := global.GVA_DB
if template.DBName != "" {
db = global.MustGetGlobalDBByDBName(template.DBName)
}

db = db.Select(strings.Join(columns, ", ")).Table(template.TableName)


for _, join := range template.JoinTemplate {
db = db.Joins(join.JOINS + "`" + join.Table + "` ON " + join.ON)
}


for _, cond := range template.Conditions {
val := values.Get(cond.From)
if val == "" {
continue
}
if cond.Operator == "LIKE" {
val = "%" + val + "%"
}
db = db.Where(fmt.Sprintf("%s %s ?", cond.Column, cond.Operator), val)
}


if limitStr := values.Get("limit"); limitStr != "" {
if limit, err := strconv.Atoi(limitStr); err == nil {
db = db.Limit(limit)
}
} else if template.Limit > 0 {
db = db.Limit(template.Limit)
}

if offsetStr := values.Get("offset"); offsetStr != "" {
if offset, err := strconv.Atoi(offsetStr); err == nil {
db = db.Offset(offset)
}
}


if order := values.Get("order"); order != "" {
db = db.Order(order)
} else if template.Order != "" {
db = db.Order(template.Order)
}


var result []map[string]interface{}
if err := db.Find(&result).Error; err != nil {
return nil, "", err
}


for _, rowMap := range result {
row := make([]string, 0, len(columns))
for _, rawCol := range columns {
col := rawCol
if len(template.JoinTemplate) > 0 {
if parts := strings.Split(rawCol, " as "); len(parts) > 1 {
col = strings.TrimSpace(parts[1])
} else if parts := strings.Split(rawCol, "."); len(parts) > 1 {
col = parts[1]
}
}
row = append(row, fmt.Sprintf("%v", rowMap[col]))
}
rows = append(rows, row)
}


for rowIdx, row := range rows {
for colIdx, val := range row {
cell := fmt.Sprintf("%s%d", getColumnName(colIdx+1), rowIdx+1)
if err := xlsx.SetCellValue("Sheet1", cell, val); err != nil {
return nil, "", err
}
}
}

xlsx.SetActiveSheet(sheetIdx)
buffer, err := xlsx.WriteToBuffer()
if err != nil {
return nil, "", err
}
return buffer, template.Name, nil
}



func (svc *SysExportTemplateService) ExportTemplate(templateID string) (*bytes.Buffer, string, error) {
var tpl system.SysExportTemplate


if err := global.GVA_DB.First(&tpl, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

excel := excelize.NewFile()
defer func() {
