function getNav(currentPage, isSubDir) {

var countRows = wait.forMethod(connection, 'query', 'SELECT COUNT(*) AS namesCount FROM bi_posts');
var navHtml = '<div id="pageNav">';

var totalPosts = countRows[0].namesCount;
var postsPerPage = app.locals.postperpage;
var totalPages = Math.ceil(totalPosts / postsPerPage);


if (currentPage !== 1) {
var previousPage = currentPage - 1;
navHtml += '<a href="' + previousPage + '" class="button pagenav">上一页</a>';
}


for (var i = 0; i < totalPages; i++) {
var pageIndex = i + 1;
var pageUrl = isSubDir ? pageIndex : "page/" + pageIndex;
var pageClass = currentPage === pageIndex ? 'button pagenav current' : 'button pagenav';
navHtml += '<a href="' + pageUrl + '" class="' + pageClass + '">' + pageIndex + '</a>';
}


var nextPage = parseInt(currentPage) + 1;
var hasNext = currentPage !== totalPages;

if (hasNext) {
var nextHref = isSubDir ? nextPage : "page/" + nextPage;
navHtml += '<a href="' + nextHref + '" class="button pagenav">下一页</a>';
}

navHtml += '</div>';


cache.put("nav-" + currentPage, navHtml);
}

function searchkey(userQuery, responseObj) {
var sql = 'select * from bi_posts where concat(title,content) like "%' + userQuery + '%"';

connection.query(sql, function(err, rowList) {
if (err) {
log(err, 3);
}

if (rowList[0] === undefined) {
responseObj.contentType('application/json');
responseObj.send('{"error":2}');
return;
}

var result = {
"error": 0,
"results": {}
};

for (var i = 0, len = rowList.length; i < len; i++) {
var rawContent = rowList[i].content;
var cleanText = rawContent.replace(/(<([^>]+)>)/ig, "").replace(/\r?\n|\r/g, " ").substr(0, 200);

result.results[i] = {
"id": rowList[i].id,
"time": rowList[i].time,
"title": rowList[i].title,
"category": cache.get('categorydata-' + rowList[i].category),
"shortname": rowList[i].shortname,
"content": cleanText,
"firstimg": getFirstImage(rawContent)
};
}

if (CACHE_ENABLE === 1) {
cache.put('api-search-' + userQuery, result);
cache_miss++;
responseObj.set('X-Builtin-Cache', 'miss');
}

var jsonResult = JSON.stringify(result);
responseObj.contentType('application/json');
responseObj.send(jsonResult);
});
}


