Survey.title AS stitle, Survey.description AS sdesc, Survey.id AS sid, Survey.holder
FROM Section, Survey
WHERE Survey.sectionId = Section.id
AND Section.status = 1
AND Survey.status = 1
AND Survey.sectionId = ${sectionId}
`;

