});
});
});

/* test: When select a survey, show all questions and items from the survey
*/
app.all('/survey/:id', (req, res) => {
const surveyId = req.params.id;

const querySQL = `
SELECT
Survey.id AS sid, Survey.title AS stitle, Survey.description AS sdesc,
Question.id AS qid, Item.id AS iid, question, item
FROM Survey, Question, Item
WHERE Survey.id=${surveyId} AND Survey.status=1 AND Question.status=1 AND Item.status=1
AND Question.surveyId=Survey.id AND Item.questionId=Question.id
ORDER BY qid, iid
`;

if (req.method === 'GET') {
connection.query(querySQL, (err, rows) => {
if (err) {
return res.status(500).send(`Database error: ${err.message}`);
}
if (rows.length === 0) {
return res.status(404).send(`Survey ${surveyId} not found.`);
}
res.render('survey.html', { data: hashfyQuery(rows) });
});
} else if (req.method === 'POST') {
const answers = req.body;
const answeredItemIds = Object.values(answers);

let expectedQuestionCount = 0;

async.series({
getQuestionCount: (cb) => {
const countSQL = `SELECT COUNT(*) AS cnt FROM Question WHERE status=1 AND surveyId=${surveyId}`;
connection.query(countSQL, (err, rows) => {
if (err) return cb({ code: 500, msg: err.message });
if (!rows.length) return cb({ code: 404, msg: 'Survey not found' });
expectedQuestionCount = rows[0].cnt;
cb(null);
});
},
validateAndProcess: (cb) => {
if (Object.keys(answers).length < expectedQuestionCount) {

connection.query(querySQL, (err, rows) => {
if (err) return cb({ code: 500, msg: err.message });
res.render('survey.html', {
msg: 'Please answer all questions',
cache: answers,
data: hashfyQuery(rows),
});
cb(null);
});
} else {

const updateSQL = `UPDATE Item SET count = count + 1 WHERE id IN (${answeredItemIds.join(',')})`;
connection.query(updateSQL, (err) => {
if (err) return cb({ code: 500, msg: err.message });
res.redirect(`/result/${surveyId}`);
cb(null);
});
}
},
}, (err) => {
if (err) {
res.status(err.code).send(err.msg);
}
});
}
});

