/**
* Gets the tables in the database to fill the projects drop down
* @param response Response to return
*/
function getProjectTables(response) {
var projectList = [];


var sql = "SELECT TABLE_NAME as project FROM information_schema.tables WHERE TABLE_NAME LIKE 'test_%'";


var sqlQuery = connection.query(sql, function(err, rows, fields) {
if (err) {
console.log("Database error:", err);
} else {

for (var idx = 0; idx < rows.length; idx++) {
projectList[idx] = rows[idx];
}
}
});


sqlQuery.on('end', function() {
for (var i = 0; i < projectList.length; i++) {
var projObj = {};
projObj.db = projectList[i].project;
projObj.name = projectList[i].project.substring(6);
projectList[i] = projObj;
}


response.write(JSON.stringify(projectList));
response.end();
});
}

