Question.id AS qid, Item.id AS iid, question, item
FROM Survey, Question, Item
WHERE Survey.id=${id} AND Survey.status=1 AND Question.status=1 AND Item.status=1
AND Question.surveyId=Survey.id AND Item.questionId=Question.id
ORDER BY qid, iid;
`;

if (req.method === 'GET') {
connection.query(baseSql, function(err, rows) {
if (err) {
res.status(500).send("Database error: " + err.message);
return;
}
if (!rows.length) {
res.status(404).send(`Survey ${id} not found.`);
return;
}
res.render('survey.html', {
data: hashfyQuery(rows)
});
});
} else if (req.method === 'POST') {
const body = req.body;
const itemIds = Object.values(body);

let questionCount = 0;

async.series({
countQuestions: function(callback) {
connection.query(`SELECT COUNT(*) AS cntQuestion FROM Question WHERE status=1 AND surveyId=${id}`, function(err, rows) {
if (err) {
callback({ code: 500, msg: err.message });
return;
}
if (!rows.length) {
callback({ code: 404, msg: 'Survey not found' });
return;
}
questionCount = rows[0].cntQuestion;
callback(null);
});
},
validateAndUpdate: function(callback) {
if (Object.keys(body).length < questionCount) {
connection.query(baseSql, function(err, rows) {
if (err) {
callback({ code: 500, msg: err.message });
return;
}
