msg: 'Please answer all questions',
cache: body,
data: hashfyQuery(rows)
});
callback(null);
});
} else {
const updateSql = `UPDATE Item SET count=count+1 WHERE id IN (${itemIds.join(',')})`;
connection.query(updateSql, function(err) {
if (err) {
callback({ code: 500, msg: err.message });
return;
}
res.redirect(`/result/${id}`);
callback(null);
});
}
}
}, function(err) {
if (err) {
res.status(err.code).send(err.msg);
}
});
}
});


