for(var i = 0; i < rows.length; i++){
rows[i].notes = [];
tests[i] = rows[i];
}
}
});

query.on('end',function(){
if(callback){
callback(response,tests, table);
}
else {
response.write(JSON.stringify(tests));
response.end();
}
});
}

function getStats(response, filter, table){
